import os, json, numpy as np

N = 26

# -------- IO helpers --------
def read_txt_matrix(path, shape):
    try:
        arr = np.loadtxt(path)
        arr = np.array(arr, dtype=float).reshape(shape)
        return arr
    except Exception:
        return None

def load_noesis_pack():
    c = read_txt_matrix('storage/noesis/latest_centers.txt', (N, 2))
    r = read_txt_matrix('storage/noesis/latest_radii.txt', (N,))
    if c is not None and r is not None:
        return c, r
    # Fallback: grid + hole seed (tiny margins)
    r0 = 0.1 - 1e-8
    coords = [0.1, 0.3, 0.5, 0.7, 0.9]
    centers = [[x, y] for x in coords for y in coords]  # 25
    hole = np.array([0.2, 0.2])
    d = float(np.linalg.norm(hole - np.array([0.1, 0.1])))
    r_hole = d - r0 - 1e-8
    radii = [r0]*25 + [r_hole]
    return np.array(centers, float), np.array(radii, float)

# -------- parsing and canonicalization --------
def read_summary_index_base(folder):
    # Prefer tol1e8, but accept tol1e08
    for name in ['summary_tol1e8.json', 'summary_tol1e08.json']:
        p = os.path.join(folder, name)
        if os.path.isfile(p):
            try:
                with open(p, 'r') as f:
                    js = json.load(f)
                ib = js.get('index_base', None)
                return 0 if ib == 0 else (1 if ib == 1 else None)
            except Exception:
                pass
    return None

def canonicalize_label(lbl):
    # Accept xL/xR/yB/yT or xmin/xmax/ymin/ymax
    m = {'xmin':'xL','xmax':'xR','ymin':'yB','ymax':'yT',
         'xl':'xL','xr':'xR','yb':'yB','yt':'yT',
         'xL':'xL','xR':'xR','yB':'yB','yT':'yT'}
    s = str(lbl).strip()
    return m.get(s, s)

def read_boundary_csv(folder):
    # Try both suffix styles
    for fname in ['active_boundary_tol1e8.csv', 'active_boundary_tol1e08.csv']:
        path = os.path.join(folder, fname)
        if os.path.isfile(path):
            break
    else:
        return set()
    s = read_summary_index_base(folder)
    S = set()
    try:
        with open(path, 'r') as f:
            for ln, line in enumerate(f):
                if ln == 0 and not line[:1].isdigit():
                    continue  # header
                parts = line.strip().split(',')
                if len(parts) < 2:
                    continue
                i_raw, lbl_raw = parts[0].strip(), parts[1].strip()
                if len(i_raw) == 0:
                    continue
                i = int(i_raw)
                if s is None:
                    # auto-detect 0 vs 1-based
                    if i >= N:  # e.g., 26
                        i -= 1
                elif s == 1:
                    i -= 1
                lbl = canonicalize_label(lbl_raw)
                if 0 <= i < N:
                    S.add((i, lbl))
    except Exception:
        return set()
    return S

def read_pairs_csv(folder):
    for fname in ['active_pairs_tol1e8.csv', 'active_pairs_tol1e08.csv']:
        path = os.path.join(folder, fname)
        if os.path.isfile(path):
            break
    else:
        return set()
    s = read_summary_index_base(folder)
    P = set()
    try:
        with open(path, 'r') as f:
            for ln, line in enumerate(f):
                if ln == 0 and not line[:1].isdigit():
                    continue  # header
                parts = line.strip().split(',')
                if len(parts) < 2:
                    continue
                a_raw, b_raw = parts[0].strip(), parts[1].strip()
                if not a_raw or not b_raw:
                    continue
                a = int(a_raw); b = int(b_raw)
                if s is None:
                    if max(a, b) >= N:
                        a -= 1; b -= 1
                elif s == 1:
                    a -= 1; b -= 1
                if a == b:
                    continue
                i, j = (a, b) if a < b else (b, a)
                if 0 <= i < N and 0 <= j < N:
                    P.add((i, j))
    except Exception:
        return set()
    return P

def jaccard(A, B):
    inter = len(A & B)
    union = len(A | B)
    J = (inter / union) if union > 0 else 0.0
    return inter, union, J

def write_jaccard(out_base, bj, pj, sizes):
    # JSON
    js = {
        'tolerance': '1e-8',
        'boundary': {
            'intersection': bj[0], 'union': bj[1], 'jaccard': round(bj[2], 6),
            'sizes': sizes['boundary']
        },
        'pairs': {
            'intersection': pj[0], 'union': pj[1], 'jaccard': round(pj[2], 6),
            'sizes': sizes['pairs']
        }
    }
    os.makedirs(os.path.dirname(out_base), exist_ok=True)
    with open(out_base + '.json', 'w') as f:
        json.dump(js, f, indent=2, sort_keys=True)
    # CSV
    with open(out_base + '.csv', 'w') as f:
        f.write('type,intersection,union,jaccard,|A|,|B|\n')
        f.write(f'boundary,{bj[0]},{bj[1]},{bj[2]:.6f},{sizes["boundary"][0]},{sizes["boundary"][1]}\n')
        f.write(f'pairs,{pj[0]},{pj[1]},{pj[2]:.6f},{sizes["pairs"][0]},{sizes["pairs"][1]}\n')

def construct_packing():
    # Folders
    prom = 'storage/Prometheus/nmap/n26'
    noe  = 'storage/noesis/exports/sota_243'
    sci  = 'storage/Scientia/nmap/n26'

    # Read sets (robust to suffix/indexing)
    Bp = read_boundary_csv(prom); Pp = read_pairs_csv(prom)
    Bn = read_boundary_csv(noe);  Pn = read_pairs_csv(noe)
    Bs = read_boundary_csv(sci);  Ps = read_pairs_csv(sci)

    # Sizes for reporting
    sizes_pn = {'boundary': (len(Bp), len(Bn)), 'pairs': (len(Pp), len(Pn))}
    sizes_ps = {'boundary': (len(Bp), len(Bs)), 'pairs': (len(Pp), len(Ps))}

    # Compute Jaccards
    bj_pn = jaccard(Bp, Bn); pj_pn = jaccard(Pp, Pn)
    bj_ps = jaccard(Bp, Bs); pj_ps = jaccard(Pp, Ps)

    # Write outputs
    out_dir = 'storage/noesis/nmap'
    write_jaccard(os.path.join(out_dir, 'jaccard_prometheus_eval298_vs_sota243_tol1e8'),
                  bj_pn, pj_pn, sizes_pn)
    write_jaccard(os.path.join(out_dir, 'jaccard_prometheus_eval298_vs_scientia259_tol1e8'),
                  bj_ps, pj_ps, sizes_ps)

    # Log to stdout
    print('[JACCARD] Prometheus_298 vs Noesis_243 @1e-8:',
          f'Boundary J={bj_pn[2]:.6f} ({bj_pn[0]}/{bj_pn[1]}),',
          f'Pairs J={pj_pn[2]:.6f} ({pj_pn[0]}/{pj_pn[1]})')
    print('[JACCARD] Prometheus_298 vs Scientia_259 @1e-8:',
          f'Boundary J={bj_ps[2]:.6f} ({bj_ps[0]}/{bj_ps[1]}),',
          f'Pairs J={pj_ps[2]:.6f} ({pj_ps[0]}/{pj_ps[1]})')

    # Return Noesis pack unchanged
    centers, radii = load_noesis_pack()
    return centers, radii
